describe('runMapBootstrap', () => {
  it('transitions loading(map) -> loading(image) -> ready for live graph + image contracts', async () => {
    const client = createClient();

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
      attempt: 1,
      now: () => 100,
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'loading', 'ready']);
    expect(result.state.phase).toBe('ready');

    if (result.state.phase !== 'ready') {
      throw new Error('Expected ready bootstrap state.');
    }

    expect(result.state.imageTarget).toEqual({ buildingId: 7, floorNumber: 1 });
    expect(result.state.graph.graph.buildings[0]?.name).toBe('Engineering');
    expect(result.state.authRequired).toBe(false);
    expect(client.fetchMapGraph).toHaveBeenCalledTimes(1);
    expect(client.fetchFloorPlanImageContract).toHaveBeenCalledTimes(1);
  });

  it('transitions to map-phase error with endpoint diagnostics when map fetch fails', async () => {
    const client = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: 500,
          reason: 'http-error',
          attempt: 1,
          message: 'Request failed with HTTP 500.',
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected map-phase bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('map');
    expect(result.state.endpoint).toBe(`${BASE_URL}/api/map`);
    expect(result.state.reason).toBe('http-error');
  });

  it('transitions to image-phase error with timeout diagnostics when image contract fetch fails', async () => {
    const client = createClient({
      imageResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/floor-plan/7/1`,
          status: null,
          reason: 'timeout',
          attempt: 2,
          message: 'Request timed out after 2000ms.',
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected image-phase bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('image');
    expect(result.state.reason).toBe('timeout');
    expect(result.state.endpoint).toContain('/api/floor-plan/7/1');
  });

  it('treats malformed map contracts as unrecoverable bootstrap errors', async () => {
    const client = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: 200,
          reason: 'contract-validation-error',
          attempt: 1,
          message: 'Map payload failed contract validation.',
          details: ['buildings: Required'],
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
      attempt: 1,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected malformed-contract bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('map');
    expect(result.state.reason).toBe('contract-validation-error');
    expect(result.state.recoverable).toBe(false);
  });

  it('supports idempotent restart from error to loading/ready with incremented attempts', async () => {
    const failingClient = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: null,
          reason: 'network-error',
          attempt: 1,
          message: 'Network request failed.',
        },
      },
    });

    const failed = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => failingClient,
      attempt: 1,
      now: () => 1,
    });

    expect(failed.state.phase).toBe('error');

    const healthyClient = createClient();
    const recovered = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => healthyClient,
      attempt: 2,
      now: () => 2,
    });

    expect(recovered.transitions[0]).toMatchObject({
      phase: 'loading',
      currentPhase: 'map',
      attempt: 2,
    });
    expect(recovered.state.phase).toBe('ready');

    if (recovered.state.phase !== 'ready') {
      throw new Error('Expected restart attempt to reach ready state.');
    }

    expect(recovered.state.attempt).toBe(2);
    expect(recovered.state.authRequired).toBe(false);
  });
});

import type { NavGraph } from '../../src/shared/types';
import { validateNavGraphPayload } from '../domain/navGraphSchema';

export type MapApiErrorReason =
  | 'http-error'
  | 'network-error'
  | 'timeout'
  | 'aborted'
  | 'invalid-json'
  | 'contract-validation-error'
  | 'unexpected-content-type';

export interface MapApiError {
  endpoint: string;
  status: number | null;
  reason: MapApiErrorReason;
  attempt: number;
  message: string;
  details?: string[];
}

export type MapApiResult<T> =
  | {
      ok: true;
      endpoint: string;
      status: number;
      attempt: number;
      data: T;
    }
  | {
      ok: false;
      error: MapApiError;
    };

export interface MapImageContract {
  endpoint: string;
  contentType: string;
  cacheControl: string | null;
}

export interface FloorPlanTarget {
  buildingId: number;
  floorNumber: number;
}

export interface MapApiRetryPolicy {
  maxAttempts: number;
  baseDelayMs: number;
  timeoutMs: number;
}

export type Fetcher = (input: string, init?: RequestInit) => Promise<Response>;

export interface MapApiClientConfig {
  baseUrl: string;
  fetchImpl?: Fetcher;
  retryPolicy?: Partial<MapApiRetryPolicy>;
  sleep?: (ms: number) => Promise<void>;
}

export interface MapApiRequestOptions {
  signal?: AbortSignal;
  maxAttempts?: number;
  timeoutMs?: number;
}

interface AttemptSignal {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
}

interface HttpSuccess {
  ok: true;
  endpoint: string;
  attempt: number;
  response: Response;
}

interface HttpFailure {
  ok: false;
  error: MapApiError;
}

const DEFAULT_RETRY_POLICY: MapApiRetryPolicy = {
  maxAttempts: 3,
  baseDelayMs: 200,
  timeoutMs: 2_000,
};

function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'AbortError';
  }

  return error instanceof Error && error.name === 'AbortError';
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number): AttemptSignal {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
): (ms: number) => Promise<void> {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(new DOMException('Aborted', 'AbortError'));
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl: Fetcher =
    config.fetchImpl ?? ((input, init) => fetch(input, init));
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpSuccess | HttpFailure> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      const attemptSignal = createAttemptSignal(options?.signal, timeoutMs);

      try {
        const response = await fetchImpl(endpoint, {
          method: 'GET',
          signal: attemptSignal.signal as unknown as RequestInit['signal'],
        });

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            await sleepWithSignal(delay);
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const reason: MapApiErrorReason = attemptSignal.didTimeout()
          ? 'timeout'
          : options?.signal?.aborted || isAbortError(error)
            ? 'aborted'
            : 'network-error';

        const apiError = createApiError(
          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

        const shouldRetry = reason !== 'aborted' && attempt < maxAttempts;
        if (shouldRetry) {
          lastError = apiError;
          const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
          await sleepWithSignal(delay);
          continue;
        }

        return { ok: false, error: apiError };
      } finally {
        attemptSignal.cleanup();
      }
    }

    return {
      ok: false,
      error:
        lastError ??
        createApiError(endpoint, maxAttempts, 'network-error', 'Request failed after retries.'),
    };
  }

  async function fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>> {
    const endpoint = resolveMapEndpoint(baseUrl);
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    let payload: unknown;

    try {
      payload = await responseResult.response.json();
    } catch (error) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'invalid-json',
          error instanceof Error ? error.message : 'Response body is not valid JSON.',
          responseResult.response.status,
        ),
      };
    }

    const validated = validateNavGraphPayload(payload);
    if (!validated.ok) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'contract-validation-error',
          validated.error.message,
          responseResult.response.status,
          validated.error.issues,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: validated.data,
    };
  }

  async function fetchImageContract(
    endpoint: string,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    const contentType = responseResult.response.headers.get('content-type');
    if (!contentType || !contentType.toLowerCase().startsWith('image/')) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'unexpected-content-type',
          `Expected image content-type but received "${contentType ?? 'missing'}".`,
          responseResult.response.status,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: {
        endpoint,
        contentType,
        cacheControl: responseResult.response.headers.get('cache-control'),
      },
    };
  }

  function resolveMapUrl(): string {
    return resolveMapEndpoint(baseUrl);
  }

  function resolveFloorPlanImageUrl(target: FloorPlanTarget): string {
    return resolveFloorPlanImageEndpoint(baseUrl, target);
  }

  function resolveCampusImageUrl(): string {
    return resolveCampusImageEndpoint(baseUrl);
  }

  async function fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveFloorPlanImageUrl(target), options);
  }

  async function fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveCampusImageUrl(), options);
  }

  return {
    fetchMapGraph,
    fetchFloorPlanImageContract,
    fetchCampusImageContract,
    resolveMapUrl,
    resolveFloorPlanImageUrl,
    resolveCampusImageUrl,
  };
}

export function resolveMapEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/map');
}

export function resolveFloorPlanImageEndpoint(baseUrl: string, target: FloorPlanTarget): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const buildingId = Number(target.buildingId);
  const floorNumber = Number(target.floorNumber);
  return resolveEndpoint(normalizedBaseUrl, `/api/floor-plan/${buildingId}/${floorNumber}`);
}

export function resolveCampusImageEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/campus/image');
}

import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

export const STARTUP_TIMEOUT_MS = 3_000;

export type BootstrapPhase = 'idle' | 'loading' | 'ready' | 'error';

export type BootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | 'startup-timeout'
  | 'startup-tooling-error'
  | 'invalid-startup-config';

export type BootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: BootstrapErrorReason;
      message: string;
      failedPhase: 'loading';
      recoverable: boolean;
    };

export interface BootstrapResult {
  state: BootstrapState;
  transitions: BootstrapState[];
}

export interface BootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  timeoutMs?: number;
  now?: () => number;
  toolingCheck?: () => Promise<unknown>;
}

interface ValidUrlResult {
  ok: true;
  normalizedUrl: string;
}

interface InvalidUrlResult {
  ok: false;
  reason: Extract<BootstrapErrorReason, 'missing-api-base-url' | 'invalid-api-base-url'>;
  message: string;
}

const DEFAULT_IDLE_STATE: BootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_BOOTSTRAP_STATE = DEFAULT_IDLE_STATE;

export function createLoadingState(attempt: number, now: () => number): BootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
  };
}

export function validateApiBaseUrl(rawValue: string | undefined): ValidUrlResult | InvalidUrlResult {
  const value = rawValue?.trim();

  if (!value) {
    return {
      ok: false,
      reason: 'missing-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL is missing.',
    };
  }

  try {
    const parsed = new URL(value);

    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        ok: false,
        reason: 'invalid-api-base-url',
        message: 'EXPO_PUBLIC_API_BASE_URL must use http or https.',
      };
    }

    parsed.hash = '';

    return {
      ok: true,
      normalizedUrl: parsed.toString().replace(/\/$/, ''),
    };
  } catch {
    return {
      ok: false,
      reason: 'invalid-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL must be a valid absolute URL.',
    };
  }
}

function toBootstrapError(
  reason: BootstrapErrorReason,
  message: string,
  attempt: number,
  recoverable = true,
): BootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'loading',
    recoverable,
  };
}

function isValidStartupToolingResult(result: unknown): result is { status: 'ok' } {
  return !!result && typeof result === 'object' && (result as { status?: string }).status === 'ok';
}

async function defaultToolingCheck(): Promise<{ status: 'ok' }> {
  return { status: 'ok' };
}

async function runWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }
}

export async function runAppBootstrap(options: BootstrapOptions = {}): Promise<BootstrapResult> {
  const now = options.now ?? Date.now;
  const attempt = Math.max(1, options.attempt ?? 1);
  const timeoutMs = options.timeoutMs ?? STARTUP_TIMEOUT_MS;
  const toolingCheck = options.toolingCheck ?? defaultToolingCheck;
  const env = options.env ?? process.env;

  const loadingState = createLoadingState(attempt, now);
  const transitions: BootstrapState[] = [loadingState];

  try {
    const toolingResult = await runWithTimeout(
      toolingCheck(),
      timeoutMs,
      'Startup tooling check timed out.',
    );

    if (!isValidStartupToolingResult(toolingResult)) {
      const malformedConfigState = toBootstrapError(
        'invalid-startup-config',
        'Startup tooling returned an invalid configuration shape.',
        attempt,
        false,
      );
      transitions.push(malformedConfigState);
      return {
        state: malformedConfigState,
        transitions,
      };
    }
  } catch (error) {
    const reason: BootstrapErrorReason =
      error instanceof Error && error.message === 'Startup tooling check timed out.'
        ? 'startup-timeout'
        : 'startup-tooling-error';

    const toolingErrorState = toBootstrapError(
      reason,
      error instanceof Error ? error.message : 'Startup tooling check failed.',
      attempt,
      true,
    );
    transitions.push(toolingErrorState);

    return {
      state: toolingErrorState,
      transitions,
    };
  }

  const apiValidation = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);

  if (!apiValidation.ok) {
    const configErrorState = toBootstrapError(
      apiValidation.reason,
      apiValidation.message,
      attempt,
      false,
    );
    transitions.push(configErrorState);

    return {
      state: configErrorState,
      transitions,
    };
  }

  const readyState: BootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiValidation.normalizedUrl,
  };
  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

